for i in range(q):
 a=next(it)-1;b=next(it);starts.append(a);nxt.append(head[b]);head[b]=i
for step in range(1,n+1):
 ids=[];i=head[step]
 while i>=0:ids.append(i);i=nxt[i]
 if not ids:continue
 ids.sort(key=lambda i:(starts[i]%step,-starts[i]));residue=-1;upper=n;total=0
 for i in ids:
